1	import {WebSocket} from 'ws';
2	import {createMessageHandler} from './messageHandler.js';
3	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
4	import type {ChatSession} from '../../types/session.js';
5	import type {MessageChunk} from '../../types/ai.js';
6	import type {OutgoingMessage} from '../../types/messages.js';
7	import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../../types/sessionStore.js';
8	import {InMemorySessionStore} from '../../infrastructure/stores/inMemorySessionStore.js';
9	import {deferred, eventually} from '../wsTestSupport.js';
10	
11	// The handler's own decisions, apart from the wire the acceptance suite already exercises over a real socket.
12	
13	const harness = (store: SessionStore, orchestrator: ChatOrchestrator) => {
14	  const sent: OutgoingMessage[] = [];
15	  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
16	  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
17	  // One argument per facet: the store arrives beside the orchestrator, the way createServer holds both.
18	  const handle = createMessageHandler(orchestrator, store);
19	  return {
20	    sent,
21	    ask: (frame: unknown) => handle(ws, session, frame),
22	  };
23	};
24	
25	describe('the list_sessions frame handler', () => {
26	  it("answers the session user's own list as ISO strings, forwarding limit and before and ignoring the frame's userId", async () => {
27	    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
28	    const summaries: SessionSummary[] = [
29	      {
30	        sessionId: 's2',
31	        createdAt: new Date('2026-01-01T00:00:00.000Z'),
32	        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
33	        entryCount: 4,
34	      },
35	    ];
36	    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
37	    const h = harness(
38	      {
39	        listFor: (userId: string | number, options?: SessionListOptions) => {
40	          seen.push({userId, options});
41	          return summaries;
42	        },
43	      } as unknown as SessionStore,
44	      {} as ChatOrchestrator
45	    );
46	
47	    await h.ask({type: 'list_sessions', limit: 10, before, userId: 'u2'});
48	
49	    expect({seen, sent: h.sent}).toEqual({
50	      seen: [{userId: 'u1', options: {limit: 10, before}}],
51	      sent: [
52	        {
53	          type: 'session_list',
54	          sessions: [
55	            {
56	              sessionId: 's2',
57	              createdAt: '2026-01-01T00:00:00.000Z',
58	              updatedAt: '2026-01-01T00:02:00.000Z',
59	              entryCount: 4,
60	            },
61	          ],
62	        },
63	      ],
64	    });
65	  });
66	
67	  // Held open mid-answer: the turn's lock is still taken the whole time the list is asked, so only the dispatch decides.
68	  it('answers a list_sessions asked mid-turn before that turn commits or ends, without waiting on the lock', async () => {
69	    const hold = deferred();
70	    const midAnswer: ChatOrchestrator = {
71	      processMessage: async () => 'hi',
72	      async *processMessageStream(): AsyncGenerator<MessageChunk> {
73	        yield {type: 'text', text: 'half'};
74	        await hold.until;
75	        yield {type: 'stop', stopReason: 'end_turn'};
76	      },
77	    };
78	    const h = harness(new InMemorySessionStore(), midAnswer);
79	
80	    const turn = h.ask({type: 'user_message', content: 'hello'});
81	    // The user entry and the open answer are out: the turn holds the lock from here until release.
82	    await eventually(() => h.sent.length >= 3);
83	    const answered = await Promise.race([
84	      h.ask({type: 'list_sessions'}).then(() => true),
85	      new Promise<boolean>(resolve => setTimeout(() => resolve(false), 200)),
86	    ]);
87	    hold.release();
88	    await turn;
89	
90	    expect({answeredWhileStreaming: answered, frames: h.sent.map(frame => frame.type)}).toEqual({
91	      answeredWhileStreaming: true,
