1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage, SessionSummaryFrame} from '../../types/messages.js';
6	import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendStreamEnd,
29	  sendSessionList,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  return function handleMessage(
46	    ws: WebSocket,
47	    session: ChatSession,
48	    rawMessage: unknown,
49	    signal?: AbortSignal
50	  ): Promise<void> {
51	    const validation = validateMessage(rawMessage);
52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
53	    if (isUserMessageFrame(rawMessage)) {
54	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
55	    }
56	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
57	    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore));
58	  };
59	}
60	
61	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
62	async function answerInTurn(
63	  ws: WebSocket,
64	  session: ChatSession,
65	  orchestrator: ChatOrchestrator,
66	  validation: ValidationResult,
67	  signal: AbortSignal | undefined
68	): Promise<void> {
69	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
70	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
71	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
72	    return;
73	  }
74	  const startedAt = Date.now();
75	  try {
76	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
77	  } finally {
78	    endTurn(ws, session, signal, startedAt);
79	  }
80	}
81	
82	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
83	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
84	  if (signal?.aborted) {
85	    log.info('message', 'turn abandoned: its socket closed', {
86	      sessionId: session.sessionId,
87	      elapsedMs: Date.now() - startedAt,
88	    });
89	    return;
90	  }
91	  sendStreamEnd(ws);
92	}
93	
94	async function answerUserMessage(
95	  ws: WebSocket,
96	  session: ChatSession,
97	  orchestrator: ChatOrchestrator,
98	  validation: ValidationResult,
99	  signal: AbortSignal | undefined
100	): Promise<void> {
101	  const message = validation.valid ? validation.data : undefined;
102	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
103	  await answerFrame(ws, session, validation, undefined);
104	}
105	
106	async function answerFrame(
107	  ws: WebSocket,
108	  session: ChatSession,
109	  validation: ValidationResult,
110	  sessionStore: SessionStore | undefined
111	): Promise<void> {
112	  if (!validation.valid) {
113	    log.warn('message', 'validation failed', {error: validation.error});
114	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
115	    return;
116	  }
117	
118	  const message = validation.data;
119	  if (message.type === 'ping') handlePing(ws, message.timestamp);
120	  if (message.type === 'list_sessions') await answerSessionList(ws, session, message, sessionStore);
121	}
122	
123	// Beside ping, off the lock: a history request is not a turn and must not queue behind a streaming answer.
124	async function answerSessionList(
125	  ws: WebSocket,
126	  session: ChatSession,
127	  message: ListSessionsMessage,
128	  sessionStore: SessionStore | undefined
129	): Promise<void> {
130	  // A store of the five required members is a valid store: its users have no list yet, which is an empty list, not a refusal.
131	  if (!sessionStore?.listFor) {
132	    sendSessionList(ws, []);
133	    return;
134	  }
135	  try {
136	    // The connection's user, never one the frame named: the list is always the authenticated user's own.
137	    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
138	    sendSessionList(ws, summaries.map(sessionSummaryFrame));
139	  } catch (error) {
140	    const detail = error instanceof Error ? error.message : String(error);
141	    log.error('ws', 'session list failed', {sessionId: session.sessionId, userId: session.userId, error: detail});
142	    // The store's detail stays in the log; the frame a client renders names no store behind it.
143	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
144	  }
145	}
146	
147	function sessionSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
148	  return {
149	    sessionId: summary.sessionId,
150	    createdAt: isoOf(summary.createdAt),
151	    updatedAt: isoOf(summary.updatedAt),
152	    entryCount: summary.entryCount,
153	  };
154	}
155	
156	// `new Date` on a Date is a copy, so a store that kept its word about ISO strings still serialises.
157	function isoOf(moment: Date): string {
158	  return new Date(moment).toISOString();
159	}
160	
161	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
162	function isUserMessageFrame(rawMessage: unknown): boolean {
163	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
164	}
165	
166	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
167	  try {
168	    await action();
169	  } catch (error) {
170	    const message = error instanceof Error ? error.message : 'Unknown error';
171	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
172	    log.error('message', 'handling error', {error: message, code});
173	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
174	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
175	      return;
176	    }
177	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
178	  }
179	}
180	
181	async function handleUserMessage(
182	  ws: WebSocket,
183	  session: ChatSession,
184	  orchestrator: ChatOrchestrator,
185	  content: string,
186	  signal: AbortSignal | undefined
187	): Promise<void> {
188	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
189	
190	  const userEntry = createUserEntry(content);
191	  const userIndex = appendEntry(session, userEntry);
192	  sendUpsert(ws, userIndex, userEntry);
193	
194	  const parser = new ThinkingTagParser();
195	  const state: StreamState = {
196	    thinkingIndex: null,
197	    assistantIndex: null,
198	    suppressOutput: false,
199	    sentAssistantIndices: [],
200	  };
201	
202	  let textChunkCount = 0;
203	
204	  try {
205	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
206	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
207	      if (signal?.aborted) break;
208	      textChunkCount = logChunk(chunk, textChunkCount);
209	      processChunk(ws, session, state, parser, chunk);
210	    }
211	  } finally {
212	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
213	    flushHeldText(ws, session, state, parser);
214	    closeCutOff(ws, session, state, 'thinkingIndex');
215	    closeCutOff(ws, session, state, 'assistantIndex');
216	  }
217	
218	  if (textChunkCount > 0) {
219	    log.debug('stream', `received ${textChunkCount} text chunks`);
220	  }
221	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
222	}
223	
224	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
225	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
226	  if (chunk.type === 'text') return textChunkCount + 1;
227	
228	  if (textChunkCount > 0) {
229	    log.debug('stream', `received ${textChunkCount} text chunks`);
230	  }
231	
232	  if (chunk.type === 'tool_result') {
233	    log.debug('stream', 'tool_result chunk', {
234	      messageCount: chunk.clientMessages.length,
235	      types: chunk.clientMessages.map(m => m.type),
236	    });
237	    return 0;
238	  }
239	
240	  log.debug('stream', 'chunk', {type: chunk.type});
241	  return 0;
242	}
243	
244	function processChunk(
245	  ws: WebSocket,
246	  session: ChatSession,
247	  state: StreamState,
248	  parser: ThinkingTagParser,
249	  chunk: MessageChunk
250	): void {
251	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
252	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
253	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
254	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
255	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
256	}
257	
258	function processTextChunk(
259	  ws: WebSocket,
260	  session: ChatSession,
261	  state: StreamState,
262	  parser: ThinkingTagParser,
263	  text: string
264	): void {
265	  const segments = parser.push(text);
266	  for (const segment of segments) {
267	    handleTextSegment(ws, session, state, segment);
268	  }
269	}
270	
271	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
272	  if (segment.type === 'thinking') {
273	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
274	    return;
275	  }
276	  commitAndClear(ws, session, state, 'thinkingIndex');
277	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
278	}
279	
280	function streamSegment(
281	  ws: WebSocket,
282	  session: ChatSession,
283	  state: StreamState,
284	  key: StateIndexKey,
285	  createEntry: EntryFactory,
286	  content: string
287	): void {
288	  const isNew = initSegment(session, state, key, createEntry);
289	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
290	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
291	  appendDelta(session, state[key]!, content);
292	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
293	}
294	
295	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
296	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
297	  markSuppressed(session, index);
298	  sendSkip(ws, index);
299	}
300	
301	function markSuppressed(session: ChatSession, index: number): void {
302	  const entry = session.entries[index];
303	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
304	}
305	
306	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
307	  if (state[key] !== null) return false;
308	  state[key] = appendEntry(session, createEntry());
309	  return true;
310	}
311	
312	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
313	  const index = state[key];
314	  if (index === null) return;
315	
316	  commitEntry(session, index);
317	  state[key] = null;
318	
319	  // Only what the client received can be retracted, and only assistant entries.
320	  if (state.suppressOutput) return;
321	
322	  sendCommit(ws, index);
323	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
324	}
325	
326	function processToolUseChunk(
327	  ws: WebSocket,
328	  session: ChatSession,
329	  toolCall: {name: string; input: Record<string, unknown>}
330	): void {
331	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
332	  const toolIndex = appendEntry(session, toolEntry);
333	  sendUpsert(ws, toolIndex, toolEntry);
334	}
335	
336	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
337	  for (const msg of clientMessages) {
338	    log.debug('stream', 'forwarding client message to frontend', {
339	      type: msg.type,
340	      index: 'index' in msg ? msg.index : undefined,
341	    });
342	    sendJson(ws, msg);
343	  }
344	}
345	
346	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
347	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
348	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
349	  commitOpenEntries(ws, session, state);
350	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
351	
352	  for (const idx of state.sentAssistantIndices) {
353	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
354	    markSuppressed(session, idx);
355	  }
356	
357	  state.sentAssistantIndices = [];
358	  state.suppressOutput = true;
359	}
360	
361	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
362	  flushHeldText(ws, session, state, parser);
363	  commitOpenEntries(ws, session, state);
364	}
365	
366	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
367	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
368	  for (const segment of parser.flush()) {
369	    handleTextSegment(ws, session, state, segment);
370	  }
371	}
372	
373	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
374	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
375	  const index = state[key];
376	  if (index === null) return;
377	  markTruncated(session, index);
378	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
379	  commitAndClear(ws, session, state, key);
380	}
381	
382	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
383	  commitAndClear(ws, session, state, 'thinkingIndex');
384	  commitAndClear(ws, session, state, 'assistantIndex');
385	}
386	
387	function handlePing(ws: WebSocket, timestamp: number): void {
388	  ws.send(JSON.stringify({type: 'pong', timestamp}));
389	}
390

